package main

import (
        "fmt"
        "os"
        "path/filepath"
)

func cmdValidate(args []string) {
        if len(args) < 1 {
                fmt.Fprintf(os.Stderr, "usage: mlpipe validate <model>\n")
                os.Exit(1)
        }
        name := args[0]

        entries, err := loadRegistry()
        if err != nil {
                fmt.Fprintf(os.Stderr, "error: %v\n", err)
                os.Exit(1)
        }

        entry := findEntry(entries, name)
        if entry == nil {
                fmt.Fprintf(os.Stderr, "error: model '%s' not found\n", name)
                os.Exit(1)
        }
        if !modelDirExists(entry.Path) {
                fmt.Fprintf(os.Stderr, "error: model directory not found\n")
                os.Exit(1)
        }

        errors := validateModel(entry.Path)
        if len(errors) == 0 {
                fmt.Printf("Model '%s' is valid.\n", name)
        } else {
                fmt.Printf("Model '%s' has %d validation error(s):\n", name, len(errors))
                for i, e := range errors {
                        fmt.Printf("  %d. %s\n", i+1, e)
                }
                os.Exit(1)
        }
}

func validateModel(modelDir string) []string {
        var errors []string

        metaPath := filepath.Join(modelDir, "model.meta")
        if _, err := os.Stat(metaPath); err != nil {
                errors = append(errors, "missing model.meta")
        } else {
                meta, err := loadModelMeta(modelDir)
                if err != nil {
                        errors = append(errors, fmt.Sprintf("cannot parse model.meta: %v", err))
                } else {
                        if meta["name"] == "" {
                                errors = append(errors, "model.meta: missing 'name' field")
                        }
                        if meta["type"] == "" {
                                errors = append(errors, "model.meta: missing 'type' field")
                        }
                        if meta["features"] == "" {
                                errors = append(errors, "model.meta: missing 'features' field")
                        }
                        if meta["outputs"] == "" {
                                errors = append(errors, "model.meta: missing 'outputs' field")
                        }
                }
        }

        weightsPath := filepath.Join(modelDir, "weights.bin")
        if _, err := os.Stat(weightsPath); err != nil {
                errors = append(errors, "missing weights.bin")
        } else {
                _, err := loadWeights(modelDir)
                if err != nil {
                        errors = append(errors, fmt.Sprintf("cannot parse weights.bin: %v", err))
                }
        }

        cfgPath := filepath.Join(modelDir, "pipeline.cfg")
        if _, err := os.Stat(cfgPath); err != nil {
                errors = append(errors, "missing pipeline.cfg")
        } else {
                _, err := loadPipelineConfig(modelDir)
                if err != nil {
                        errors = append(errors, fmt.Sprintf("cannot parse pipeline.cfg: %v", err))
                }
        }

        return errors
}

