New loadWeights:
func loadWeights(modelDir string) (*WeightsData, error) {
	f, err := os.Open(filepath.Join(modelDir, "weights.bin"))
	if err != nil {
		return nil, err
	}
	defer f.Close()

	magic := make([]byte, 4)
	if _, err := f.Read(magic); err != nil {
		return nil, fmt.Errorf("failed to read magic: %v", err)
	}
	if string(magic) != string(modelMagic) {
		return nil, fmt.Errorf("invalid model file: bad magic")
	}

	var ver, nf, no uint32
	if err := binary.Read(f, binary.LittleEndian, &ver); err != nil {
		return nil, fmt.Errorf("failed to read version: %v", err)
	}
	if err := binary.Read(f, binary.LittleEndian, &nf); err != nil {
		return nil, fmt.Errorf("failed to read num_features: %v", err)
	}
	if err := binary.Read(f, binary.LittleEndian, &no); err != nil {
		return nil, fmt.Errorf("failed to read num_outputs: %v", err)
	}

	var act uint32
	switch ver {
	case 1:
		act = 0
	case 2:
		if err := binary.Read(f, binary.LittleEndian, &act); err != nil {
			return nil, fmt.Errorf("failed to read activation: %v", err)
		}
	default:
		return nil, fmt.Errorf("unsupported model format version: %d", ver)
	}

	weights := make([]float64, nf*no)
	for i := range weights {
		if err := binary.Read(f, binary.LittleEndian, &weights[i]); err != nil {
			return nil, fmt.Errorf("failed to read weight[%d]: %v", i, err)
		}
	}

	bias := make([]float64, no)
	for i := range bias {
		if err := binary.Read(f, binary.LittleEndian, &bias[i]); err != nil {
			return nil, fmt.Errorf("failed to read bias[%d]: %v", i, err)
		}
	}

	return &WeightsData{
		Version:     ver,
		NumFeatures: nf,
		NumOutputs:  no,
		Activation:  act,
		Weights:     weights,
		Bias:        bias,
	}, nil
}

