func writeWeights(path string, w *WeightsData) error {
	f, err := os.Create(path)
	if err != nil {
		return err
	}
	defer f.Close()

	if _, err := f.Write(modelMagic); err != nil {
		return err
	}
	if err := binary.Write(f, binary.LittleEndian, w.Version); err != nil {
		return err
	}
	if err := binary.Write(f, binary.LittleEndian, w.NumFeatures); err != nil {
		return err
	}
	if err := binary.Write(f, binary.LittleEndian, w.NumOutputs); err != nil {
		return err
	}
	if w.Version >= 2 {
		if err := binary.Write(f, binary.LittleEndian, w.Activation); err != nil {
			return err
		}
	}
	for _, v := range w.Weights {
		if err := binary.Write(f, binary.LittleEndian, v); err != nil {
			return err
		}
	}
	for _, v := range w.Bias {
		if err := binary.Write(f, binary.LittleEndian, v); err != nil {
			return err
		}
	}
	return nil
}

const (
	activationNone = 0
	activationSigmoid = 1
	activationReLU = 2
	activationTanh = 3
)

func activationNameToID(name string) (uint32, error) {
	switch strings.ToLower(name) {
	case "", "none":
		return activationNone, nil
	case "sigmoid":
		return activationSigmoid, nil
	case "relu":
		return activationReLU, nil
	case "tanh":
		return activationTanh, nil
	default:
		return 0, fmt.Errorf("invalid activation")
	}
}

func activationIDToName(id uint32) string {
	switch id {
	case activationNone:
		return "none"
	case activationSigmoid:
		return "sigmoid"
	case activationReLU:
		return "relu"
	case activationTanh:
		return "tanh"
	default:
		return "unknown"
	}
}

func applyActivation(x float64, activation uint32) float64 {
	switch activation {
	case activationSigmoid:
		return 1.0 / (1.0 + math.Exp(-x))
	case activationReLU:
		if x < 0 {
			return 0
		}
		return x
	case activationTanh:
		return math.Tanh(x)
	default:
		return x
	}
}

