func cmdCompat(args []string) {
	flags := parseFlags(args)
	all := flags["all"] == "true" || flags["all"] == "1"
	entries, err := loadRegistry()
	if err != nil {
		fmt.Fprintf(os.Stderr, "error: %v\n", err)
		os.Exit(1)
	}
	for _, e := range entries {
		var version uint32
		status := "current"
		if !modelDirExists(e.Path) {
			version = 0
			status = "not_found"
		} else {
			w, err := loadWeights(e.Path)
			if err != nil {
				version = 0
				status = "error"
			} else {
				version = w.Version
				switch version {
				case 1:
					status = "needs_migration"
				case 2:
					status = "current"
				default:
					status = "unknown"
				}
			}
		}
		if !all && status != "needs_migration" {
			continue
		}
		fmt.Printf("%s v%d %s\n", e.Name, version, status)
	}
}

